use axum::{Router,body::{Body,Bytes},extract::{Path,State},response::IntoResponse,routing::post};
use http_body_util::BodyExt;
#[derive(Clone)]struct ClientState{client:reqwest::Client,base:String}
fn size(id:usize)->usize{match id%3{1=>64,2=>4096,_=>65537}}
fn payload(count:usize,offset:usize,id:usize)->Vec<u8>{(0..count).map(|i|(((offset+i)*17+id)%251)as u8).collect()}
async fn sink(Path((_mode,id)):Path<(String,usize)>,mut body:Body)->impl IntoResponse{let(mut offset,mut checksum)=(0,0u64);while let Some(frame)=body.frame().await{if let Ok(chunk)=frame.unwrap().into_data(){for byte in chunk{assert_eq!(byte,((offset*17+id)%251)as u8);offset+=1;checksum=(checksum*131+u64::from(byte))%1_000_000_007;}}}assert_eq!(offset,size(id));format!("{offset},{checksum}")}
async fn forward(State(state):State<ClientState>,Path((mode,id)):Path<(String,usize)>)->impl IntoResponse{let count=size(id);let mut producer=None;
 let body=if mode=="bytes"{reqwest::Body::from(payload(count,0,id))}else if mode=="stream"{reqwest::Body::wrap_stream(Body::from(payload(count,0,id)).into_data_stream())}else{let(tx,rx)=tokio::sync::mpsc::channel(1);producer=Some(tokio::spawn(async move{let first=count/2;tx.send(Bytes::from(payload(first,0,id))).await.unwrap();tx.send(Bytes::from(payload(count-first,first,id))).await.unwrap();}));reqwest::Body::wrap_stream(futures_util::stream::unfold(rx,|mut rx|async move{rx.recv().await.map(|chunk|(Ok::<Bytes,std::io::Error>(chunk),rx))}))};
 let response=state.client.post(format!("{}/sink/{mode}/{id}",state.base)).body(body).send().await.unwrap().text().await.unwrap();if let Some(producer)=producer{producer.await.unwrap();}response}
fn main(){tokio::runtime::Builder::new_multi_thread().worker_threads(1).enable_all().build().unwrap().block_on(async{
 let backend=tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();let address=backend.local_addr().unwrap();let(stop,mut stopped)=tokio::sync::watch::channel(false);let sink=tokio::spawn(async move{axum::serve(backend,Router::new().route("/sink/{mode}/{id}",post(sink))).with_graceful_shutdown(async move{let _=stopped.changed().await;}).await.unwrap();});
 let listener=tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();let address_out=listener.local_addr().unwrap();let client=ClientState{client:reqwest::Client::builder().no_proxy().build().unwrap(),base:format!("http://{address}")};let mut stopped=stop.subscribe();let front=tokio::spawn(async move{axum::serve(listener,Router::new().route("/{mode}/{id}",post(forward)).with_state(client)).with_graceful_shutdown(async move{let _=stopped.changed().await;}).await.unwrap();});println!("{{\"address\":\"{address_out}\"}}");tokio::signal::ctrl_c().await.unwrap();let _=stop.send(true);front.await.unwrap();sink.await.unwrap();
});}
